def countingGame(x: int) -> int:
    def has_seven(n: int) -> bool:
        return "7" in str(n)

    def bad(n: int) -> bool:
        # n 含 7，或 n 是某个含 7 的数的倍数（7 本身含 7，所以 7 的倍数也在内）
        if has_seven(n):
            return True
        d = 1
        while d * d <= n:
            if n % d == 0 and (has_seven(d) or has_seven(n // d)):
                return True
            d += 1
        return False

    if bad(x):
        return -1
    nxt = x + 1
    while bad(nxt):
        nxt += 1
    return nxt


